357	    /**
358	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
359	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
360	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
361	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits.
362	     *
363	     * @param rawTelephone the telephone value as supplied by the client
364	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
365	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
366	     */
367	    private static String normalizeTelephone(String rawTelephone) {
368	        if (rawTelephone == null) {
369	            throw new InvalidTelephoneException(rawTelephone);
370	        }
371	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
372	        String e164;
373	        if (cleaned.startsWith("+")) {
374	            String digits = cleaned.substring(1);
375	            if (!digits.matches("[0-9]+")) {
376	                throw new InvalidTelephoneException(rawTelephone);
377	            }
378	            e164 = "+" + digits;
379	        } else {
380	            if (!cleaned.matches("[0-9]+")) {
381	                throw new InvalidTelephoneException(rawTelephone);
382	            }
383	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
384	            e164 = "+61" + national;
385	        }
386	        int digitCount = e164.length() - 1;
387	        if (digitCount < 8 || digitCount > 15) {
388	            throw new InvalidTelephoneException(rawTelephone);
389	        }
390	        return e164;
391	    }
