393	    /**
394	     * Determines whether any existing owner already uses the given E.164 telephone. Stored
395	     * telephones are themselves E.164, so the values are compared directly.
396	     *
397	     * @param e164Telephone the E.164 telephone of the owner being created
398	     * @return {@code true} if another owner already has the same E.164 telephone
399	     */
400	    private boolean isTelephoneInUse(String e164Telephone) {
401	        return this.clinicService.findAllOwners().stream()
402	            .map(Owner::getTelephone)
403	            .filter(existing -> existing != null)
404	            .anyMatch(e164Telephone::equals);
405	    }
406	
407	    /**
408	     * Determines whether any existing owner already shares a household with the owner being created,
409	     * i.e. has both the same last name and the same address. Both fields are compared
410	     * case-insensitively after collapsing runs of whitespace to a single space and trimming.
411	     *
412	     * @param lastName the last name of the owner being created
413	     * @param address the address of the owner being created
414	     * @return {@code true} if another owner already has the same last name and address
415	     */
416	    private boolean isHouseholdInUse(String lastName, String address) {
417	        String normalizedLastName = normalizeIdentity(lastName);
418	        String normalizedAddress = normalizeIdentity(address);
419	        return this.clinicService.findAllOwners().stream()
420	            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
421	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress));
422	    }
423	
424	    /**
425	     * Counts how many existing owners already share the given first name and last name with the
426	     * owner being created. Both names are compared case-insensitively (after trimming and
427	     * collapsing runs of whitespace). The count reflects the state before the new owner is
428	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
429	     *
430	     * @param firstName the first name of the owner being created
431	     * @param lastName the last name of the owner being created
432	     * @return the number of existing owners sharing the same first and last name
433	     */
434	    private int namesakeCount(String firstName, String lastName) {
435	        String normalizedFirstName = normalizeIdentity(firstName);
436	        String normalizedLastName = normalizeIdentity(lastName);
437	        return (int) this.clinicService.findAllOwners().stream()
438	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
439	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
440	            .count();
441	    }
442	
443	    /**
444	     * Counts how many members the owner being created belongs to in its household, including
445	     * itself, as of this create. Members are the owners sharing the given {@code householdId};
446	     * the new owner is not yet persisted, so its own membership is added to the existing count.
447	     * An owner not assigned to a shared household ({@code householdId} is {@code null}) is a
448	     * household of one.
449	     *
450	     * @param householdId the shared household identifier assigned to the owner being created, or
451	     *                    {@code null} if the owner does not share a household
452	     * @return the number of household members after this create (at least 1)
453	     */
454	    private int householdSizeAfterCreate(String householdId) {
455	        if (householdId == null) {
456	            return 1;
457	        }
458	        long existing = this.clinicService.findAllOwners().stream()
459	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
460	            .count();
461	        return (int) existing + 1;
462	    }
463	
464	    /**
465	     * The maximum number of owners permitted in a single city. Once a city already contains this
466	     * many owners it is considered full and no further owners may be created there.
467	     */
468	    private static final int CITY_CAPACITY = 50;
469	
470	    /**
471	     * Determines whether the given city has already reached its capacity, i.e. already contains
472	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
473	     * collapsing runs of whitespace to a single space and trimming.
474	     *
475	     * @param city the city of the owner being created
476	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
477	     */
478	    private boolean isCityAtCapacity(String city) {
479	        String normalizedCity = normalizeIdentity(city);
480	        long count = this.clinicService.findAllOwners().stream()
481	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
482	            .count();
483	        return count >= CITY_CAPACITY;
484	    }
485	
486	    /**
487	     * The maximum number of owners that may be created on any single day. Once this many owners
488	     * already carry a {@code registrationDate} of the current day, no further owners may be created
489	     * that day.
490	     */
491	    private static final int DAILY_REGISTRATION_LIMIT = 100;
492	
493	    /**
494	     * Determines whether the daily registration limit has already been reached, i.e. whether
495	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
496	     * their {@code registrationDate}.
497	     *
498	     * @param date the current day
499	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
500	     *         registered on the given date
501	     */
502	    /**
503	     * Rolls a registration date forward onto a business day. A date that already falls on a
504	     * weekday is returned unchanged; a Saturday or Sunday is rolled forward to the following
505	     * Monday. This adjusted date is what gets stored as the {@code registrationDate} and drives
506	     * everything derived from it (the membership number's year segment, the daily create-limit).
507	     *
508	     * @param date the effective registration date (supplied by the client or defaulted to the
509	     *             server's current date)
510	     * @return the same date if it is a weekday, otherwise the following Monday
511	     */
512	    private static LocalDate toBusinessDay(LocalDate date) {
513	        DayOfWeek dayOfWeek = date.getDayOfWeek();
514	        if (dayOfWeek == DayOfWeek.SATURDAY) {
515	            return date.plusDays(2);
516	        }
517	        if (dayOfWeek == DayOfWeek.SUNDAY) {
518	            return date.plusDays(1);
519	        }
520	        return date;
521	    }
522	
523	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
524	        long count = this.clinicService.findAllOwners().stream()
525	            .filter(existing -> date.equals(existing.getRegistrationDate()))
526	            .count();
527	        return count >= DAILY_REGISTRATION_LIMIT;
528	    }
529	
530	    /**
531	     * The number of owners that may be created on a single day before the bulk-signup warning is
532	     * raised. Once <em>more than</em> this many owners already carry the current business day as
533	     * their {@code registrationDate}, responses flag {@code bulkSignupWarning} true.
534	     */
535	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
536	
537	    /**
538	     * Determines whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
539	     * created today, i.e. already carry the current business day as their {@code registrationDate}.
540	     * This shares the daily create-limit's accumulation path (owners counted by registration date).
541	     *
542	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners are already
543	     *         registered on today's business day
544	     */
545	    private boolean isBulkSignupWarning() {
546	        LocalDate today = toBusinessDay(LocalDate.now());
547	        long count = this.clinicService.findAllOwners().stream()
548	            .filter(existing -> today.equals(existing.getRegistrationDate()))
549	            .count();
550	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
551	    }
552	
553	    /**
554	     * Assigns the owner being created to the household identified by the given last name and
555	     * address and returns the household's stable shared identifier. The identifier is derived
556	     * deterministically from the normalized last name and address, so every member of the same
557	     * household resolves to the same value regardless of creation order. Any existing member that
558	     * does not yet carry the identifier is back-filled so all household members share it.
559	     *
560	     * @param lastName the last name of the owner being created
561	     * @param address the address of the owner being created
562	     * @return the stable household identifier shared by all members of the household
563	     */
564	    private String joinHousehold(String lastName, String address) {
565	        String householdId = householdIdFor(lastName, address);
566	        String normalizedLastName = normalizeIdentity(lastName);
567	        String normalizedAddress = normalizeIdentity(address);
568	        for (Owner existing : this.clinicService.findAllOwners()) {
569	            if (normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
570	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress)
571	                && !householdId.equals(existing.getHouseholdId())) {
572	                existing.setHouseholdId(householdId);
573	                this.clinicService.saveOwner(existing);
574	            }
575	        }
576	        return householdId;
577	    }
578	
579	    /**
580	     * Derives the stable household identifier for a given last name and address. The value is the
581	     * first 16 upper-case hex characters of the SHA-256 digest of the normalized last name and
582	     * address, so it is stable across calls and identical for every member of the household.
583	     *
584	     * @param lastName the last name of the household
585	     * @param address the address of the household
586	     * @return the stable household identifier
587	     */
588	    private static String householdIdFor(String lastName, String address) {
589	        String key = normalizeIdentity(lastName) + "\n" + normalizeIdentity(address);
590	        try {
591	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
592	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
593	            StringBuilder sb = new StringBuilder(digest.length * 2);
594	            for (byte b : digest) {
595	                sb.append(String.format("%02x", b));
596	            }
597	            return sb.substring(0, 16).toUpperCase(java.util.Locale.ROOT);
598	        }
599	        catch (java.security.NoSuchAlgorithmException e) {
600	            throw new IllegalStateException("SHA-256 not available", e);
601	        }
602	    }
603	
604	    /**
605	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
606	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
607	     * single space, and the result is lower-cased.
608	     *
609	     * @param value the raw field value
610	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
611	     */
612	    private static String normalizeIdentity(String value) {
613	        if (value == null) {
614	            return "";
615	        }
616	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
617	    }
618	}
