35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	
57	    /**
58	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
59	     * class.
60	     *
61	     * @param e     Object referring to the thrown exception.
62	     * @param status HTTP response status.
63	     * @param url URL request.
64	     */
65	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
66	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
67	        problemDetail.setType(URI.create(url.toString()));
68	        problemDetail.setTitle(e.getClass().getSimpleName());
69	        problemDetail.setDetail(detail);
70	        problemDetail.setProperty("timestamp", Instant.now());
71	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
72	        return problemDetail;
73	    }
74	
75	    /**
76	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
77	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
78	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
79	     * would catch it and report an authorization failure as a 500.
80	     *
81	     * @param e The {@link AccessDeniedException} to propagate
82	     * @throws AccessDeniedException always
83	     */
84	    @ExceptionHandler(AccessDeniedException.class)
85	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
86	        throw e;
87	    }
88	
89	    /**
90	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
91	     *
92	     * @param e The {@link Exception} to be handled
93	     * @param request {@link HttpServletRequest} object referring to the current request.
94	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
95	     */
96	    @ExceptionHandler(Exception.class)
97	    @ResponseBody
98	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
99	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
100	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
101	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
102	        return ResponseEntity.status(status).body(detail);
103	    }
104	
105	    /**
106	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
107	     * method returns a 404 Not Found status if an entity does not exist.
108	     *
109	     * @param e The {@link DataIntegrityViolationException} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
112	     */
113	    @ExceptionHandler(DataIntegrityViolationException.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
116	        logger.warn("Data integrity violation at {} {}: {}",
117	            request.getMethod(),
118	            request.getRequestURI(),
119	            e.getMessage());
120	        logger.debug("Data integrity violation stacktrace", e);
121	        HttpStatus status = HttpStatus.NOT_FOUND;
122	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
123	        return ResponseEntity.status(status).body(detail);
124	    }
125	
126	    /**
127	     * Handles exception thrown by Bean Validation on controller methods parameters
128	     *
129	     * @param e The {@link MethodArgumentNotValidException} to be handled
130	     * @param request {@link HttpServletRequest} object referring to the current request.
131	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
132	     */
133	    @ExceptionHandler(MethodArgumentNotValidException.class)
134	    @ResponseBody
135	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
136	        HttpStatus status = HttpStatus.BAD_REQUEST;
137	        BindingErrorsResponse errors = new BindingErrorsResponse();
138	        BindingResult bindingResult = e.getBindingResult();
139	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
140	        if (bindingResult.hasErrors()) {
141	            errors.addAllErrors(bindingResult);
142	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
143	                .map(fieldError -> {
144	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
145	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
146	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
147	                        fieldError.getField(),
148	                        defaultMessage,
149	                        rejectedValue);
150	                    return new ValidationMessageDto(message)
151	                        .putAdditionalProperty("field", fieldError.getField())
152	                        .putAdditionalProperty("rejectedValue", rejectedValue)
153	                        .putAdditionalProperty("defaultMessage", defaultMessage);
154	                })
155	                .toList();
156	            logger.debug("Validation error at {} {}: {}",
157	                request.getMethod(),
158	                request.getRequestURI(),
159	                bindingResult.getFieldErrors());
160	            List<String> errorFields = bindingResult.getFieldErrors().stream()
161	                .map(FieldError::getField)
162	                .distinct()
163	                .toList();
164	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
165	            detail.setProperty("errors", errorFields);
166	            return ResponseEntity.status(status).body(detail);
167	        }
168	        return ResponseEntity.status(status).body(detail);
169	    }
170	
171	    /**
172	     * Handles {@link InvalidTelephoneException} raised when a request to create an owner supplies a
173	     * telephone that does not normalize to exactly ten digits.
174	     *
175	     * @param e The {@link InvalidTelephoneException} to be handled
176	     * @param request {@link HttpServletRequest} object referring to the current request.
177	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status,
178	     *         whose {@code errors} array names the {@code telephone} field.
179	     */
180	    @ExceptionHandler(InvalidTelephoneException.class)
181	    @ResponseBody
182	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
183	        HttpStatus status = HttpStatus.BAD_REQUEST;
184	        logger.debug("Invalid telephone at {} {}: {}",
185	            request.getMethod(),
186	            request.getRequestURI(),
187	            e.getRejectedValue());
188	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
189	        detail.setProperty("errors", List.of("telephone"));
190	        return ResponseEntity.status(status).body(detail);
191	    }
192	
193	    /**
194	     * Handles {@link DuplicateTelephoneException} raised when a request to create an owner supplies a
195	     * telephone whose normalized value already belongs to another owner.
196	     *
197	     * @param e The {@link DuplicateTelephoneException} to be handled
198	     * @param request {@link HttpServletRequest} object referring to the current request.
199	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status,
200	     *         whose {@code errors} array names the {@code telephone} field.
201	     */
202	    @ExceptionHandler(DuplicateTelephoneException.class)
203	    @ResponseBody
204	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
205	        HttpStatus status = HttpStatus.CONFLICT;
206	        logger.debug("Duplicate telephone at {} {}: {}",
207	            request.getMethod(),
208	            request.getRequestURI(),
209	            e.getRejectedValue());
210	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
211	        detail.setProperty("errors", List.of("telephone"));
212	        return ResponseEntity.status(status).body(detail);
213	    }
214	
215	    /**
216	     * Handles {@link DuplicateHouseholdException} raised when a request to create an owner supplies a
217	     * last name and address that (compared case-insensitively with collapsed whitespace) already
218	     * belong to another owner, and the request did not opt in via {@code sharesHousehold}.
219	     *
220	     * @param e The {@link DuplicateHouseholdException} to be handled
221	     * @param request {@link HttpServletRequest} object referring to the current request.
222	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status,
223	     *         whose {@code errors} array names the {@code lastName} and {@code address} fields.
224	     */
225	    @ExceptionHandler(DuplicateHouseholdException.class)
226	    @ResponseBody
227	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
228	        HttpStatus status = HttpStatus.CONFLICT;
229	        logger.debug("Duplicate household at {} {}: {} / {}",
230	            request.getMethod(),
231	            request.getRequestURI(),
232	            e.getLastName(),
233	            e.getAddress());
234	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
235	        detail.setProperty("errors", List.of("lastName", "address"));
236	        return ResponseEntity.status(status).body(detail);
237	    }
238	
239	    /**
240	     * Handles {@link CityAtCapacityException} raised when a request to create an owner names a city
241	     * that already contains 50 or more owners.
242	     *
243	     * @param e The {@link CityAtCapacityException} to be handled
244	     * @param request {@link HttpServletRequest} object referring to the current request.
245	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status,
246	     *         whose {@code errors} array names the {@code city} field.
247	     */
248	    @ExceptionHandler(CityAtCapacityException.class)
249	    @ResponseBody
250	    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
251	        HttpStatus status = HttpStatus.CONFLICT;
252	        logger.debug("City at capacity at {} {}: {}",
253	            request.getMethod(),
254	            request.getRequestURI(),
255	            e.getCity());
256	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
257	        detail.setProperty("errors", List.of("city"));
258	        return ResponseEntity.status(status).body(detail);
259	    }
260	
261	    /**
262	     * Handles {@link DailyRegistrationLimitException} raised when a request to create an owner would
263	     * exceed the daily registration limit, i.e. 100 or more owners have already been created today.
264	     *
265	     * @param e The {@link DailyRegistrationLimitException} to be handled
266	     * @param request {@link HttpServletRequest} object referring to the current request.
267	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests
268	     *         status.
269	     */
270	    @ExceptionHandler(DailyRegistrationLimitException.class)
271	    @ResponseBody
272	    public ResponseEntity<ProblemDetail> handleDailyRegistrationLimitException(DailyRegistrationLimitException e, HttpServletRequest request) {
273	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
274	        logger.debug("Daily registration limit reached at {} {}: {}",
275	            request.getMethod(),
276	            request.getRequestURI(),
277	            e.getDate());
278	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
279	        return ResponseEntity.status(status).body(detail);
280	    }
281	
282	    /**
283	     * Handles {@link MissingOwnerFieldsException} raised when a request to create an owner omits or
284	     * blanks out one or more required fields that Bean Validation does not otherwise reject.
285	     *
286	     * @param e The {@link MissingOwnerFieldsException} to be handled
287	     * @param request {@link HttpServletRequest} object referring to the current request.
288	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status,
289	     *         whose {@code errors} array lists the name of each missing or blank field.
290	     */
291	    @ExceptionHandler(MissingOwnerFieldsException.class)
292	    @ResponseBody
293	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
294	        HttpStatus status = HttpStatus.BAD_REQUEST;
295	        logger.debug("Missing owner fields at {} {}: {}",
296	            request.getMethod(),
297	            request.getRequestURI(),
298	            e.getFields());
299	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
300	        detail.setProperty("errors", e.getFields());
301	        return ResponseEntity.status(status).body(detail);
302	    }
303	
304	}
